// 1. 建一个控制器（`main()` 里建，或挂在状态管理里）
final OhosThemeController theme = OhosThemeController();

// 2. 包住 MaterialApp
OhosThemeSwitcher(
  controller: theme,
  builder: (context, material) => MaterialApp(theme: material, home: ...),
);

// 3. 顶栏放一个按钮，点一下就在普通 / 水墨之间翻转
OhosAppBar(actions: <Widget>[OhosThemeToggleButton(controller: theme)]);

final OhosThemeController controller = OhosThemeController();

OhosThemeSwitcher(
  controller: controller,
  builder: (BuildContext context, ThemeData material) => MaterialApp(
    theme: material,
    home: const HomePage(),
  ),
);

// 任何位置，包括任意页面：
controller.toggle();

final bool? ok = await showOhosDialog<bool>(
  context: context,
  title: '删除此项？',
  content: '该操作不可恢复。',
  actions: <OhosDialogAction>[
    OhosDialogAction(label: '取消', onPressed: () => Navigator.pop(context, false)),
    OhosDialogAction(label: '删除', danger: true, onPressed: () => Navigator.pop(context, true)),
  ],
);

await showOhosBottomSheet(
  context: context,
  title: '分享',
  content: SizedBox(height: 200, child: ...),
);

// 居中形态，宽度走响应式默认：
await showOhosBottomSheet(
  context: context,
  title: '选择',
  content: ...,
  type: OhosSheetType.center,
);

final OhosCheckboxGroupController controller = OhosCheckboxGroupController(
  allNames: <String>['a', 'b', 'c'],
);

OhosCheckboxGroupScope(
  controller: controller,
  child: Column(
    children: <Widget>[
      OhosCheckboxGroupHeader(title: '全选'),
      for (final String name in controller.allNames)
        OhosCheckboxGroupTile(name: name, title: name),
    ],
  ),
)

await showOhosMenu<String>(
  context: context,
  anchor: buttonKey,
  items: const [
    OhosMenuItem(label: '复制', icon: Icons.copy, value: 'copy'),
    OhosMenuItem(label: '删除', icon: Icons.delete, value: 'delete'),
  ],
);

final String? city = await showOhosPicker<String>(
  context: context,
  title: '选择城市',
  items: const [
    OhosPickerItem(label: '北京', value: 'beijing'),
    OhosPickerItem(label: '上海', value: 'shanghai'),
  ],
  initialValue: 'beijing',
);

OhosPointLightScope(
  child: Stack(children: <Widget>[
    OhosLightSource(child: myButton),          // 按下时亮
    OhosIlluminated(illuminatedType: ..., child: myCard),
  ]),
)

showOhosPopup(
  context: context,
  content: '长按扫码支付',
  targetKey: myButtonKey,
);

OhosGrid(
  children: <Widget>[
    OhosGridItem(columnSpan: 2, child: Card(...)),
    OhosGridItem(columnSpan: 2, child: Card(...)),
  ],
)

showOhosSnackBar(
  context,
  message: '已删除 1 个文件',
  actionLabel: '撤销',
  onAction: () {},
);

// 常驻通知：duration -1 语义，显示关闭按钮，不自动消失
showOhosSnackBar(context, resident: true, icon: ..., title: 'Wi-Fi 已断开', content: '请检查网络后重试');

OhosAppBar(
  title: const Text('示例'),
  actions: <Widget>[OhosThemeToggleButton(controller: controller)],
);
